import{_ as t,o as r,c as o,a3 as a}from"./chunks/framework.D1iekJsc.js";const f=JSON.parse('{"title":"OpenRouter","description":"OpenRouter 무료 모델 — Free Models 컬렉션, :free 텍스트/비전, Key·한도, MiniTavern 입력법.","frontmatter":{"title":"OpenRouter","description":"OpenRouter 무료 모델 — Free Models 컬렉션, :free 텍스트/비전, Key·한도, MiniTavern 입력법.","head":[["meta",{"name":"keywords","content":"주점,AI 주점,MiniTavern,AI 파트너,AI 친구,AI 로컬 채팅,Silly Tavern,SillyTavern,모바일 Silly Tavern,Silly Tavern 모바일,Silly Tavern 안드로이드,Silly Tavern iOS,AI 롤플레이,캐릭터 카드,AI 채팅,모바일 AI,오프라인 AI,AI 스토리,로컬 LLM,Ollama,LM Studio,세계관,정규식,BYOK,사용자 가이드,매뉴얼"}],["meta",{"property":"og:title","content":"OpenRouter · MiniTavern Docs"}],["meta",{"property":"og:description","content":"OpenRouter 무료 모델 — Free Models 컬렉션, :free 텍스트/비전, Key·한도, MiniTavern 입력법."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ko/free-cloud/openrouter"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ko/free-cloud/openrouter"}]]},"headers":[],"relativePath":"ko/free-cloud/openrouter.md","filePath":"ko/free-cloud/openrouter.md","lastUpdated":1787224147000}'),d={name:"ko/free-cloud/openrouter.md"};function n(i,e,l,c,s,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="openrouter" tabindex="-1">OpenRouter <a class="header-anchor" href="#openrouter" aria-label="Permalink to &quot;OpenRouter&quot;">​</a></h1><p>글로벌 모델 집약 게이트웨이: Key 하나로 다수 모델. 일부는 <strong>무료 풀</strong>（ID에 <code>:free</code>, 또는 Free 표기）— 개인 체험, OSS 비교, 저빈도 롤플레이에 적합. 공식: <a href="https://openrouter.ai/collections/free-models" target="_blank" rel="noreferrer">Free Models</a>; 제3자: <a href="https://openairouter.net/free-models" target="_blank" rel="noreferrer">openairouter.net/free-models</a>（비공식, 콘솔 우선）.</p><blockquote><p>무료 목록·RPM/일 한도는 변합니다. <strong><a href="https://openrouter.ai/models?q=free" target="_blank" rel="noreferrer">openrouter.ai/models</a>와 계정 페이지 기준</strong>.</p></blockquote><h2 id="공식과-입구" tabindex="-1">공식과 입구 <a class="header-anchor" href="#공식과-입구" aria-label="Permalink to &quot;공식과 입구&quot;">​</a></h2><table tabindex="0"><thead><tr><th>자원</th><th>주소</th></tr></thead><tbody><tr><td>공식</td><td><a href="https://openrouter.ai/" target="_blank" rel="noreferrer">openrouter.ai</a></td></tr><tr><td>API Key</td><td><a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">openrouter.ai/keys</a></td></tr><tr><td>Free Models</td><td><a href="https://openrouter.ai/collections/free-models" target="_blank" rel="noreferrer">openrouter.ai/collections/free-models</a></td></tr><tr><td>광장（Free）</td><td><a href="https://openrouter.ai/models?q=free" target="_blank" rel="noreferrer">openrouter.ai/models?q=free</a></td></tr><tr><td>커뮤니티 요약（제3자）</td><td><a href="https://openairouter.net/free-models" target="_blank" rel="noreferrer">openairouter.net/free-models</a></td></tr><tr><td>API Base URL</td><td><code>https://openrouter.ai/api/v1</code>（MiniTavern <strong>OpenRouter</strong> 선택 시 보통 수동 불필요）</td></tr></tbody></table><h2 id="무료-받기" tabindex="-1">무료 받기 <a class="header-anchor" href="#무료-받기" aria-label="Permalink to &quot;무료 받기&quot;">​</a></h2><ol><li><a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">openrouter.ai/keys</a> 가입·Key（보통 <strong>카드 불필요</strong>）.</li><li><a href="https://openrouter.ai/collections/free-models" target="_blank" rel="noreferrer">Free Models</a> 또는 광장에서 <strong>Model ID</strong> 복사（<code>:free</code> 주의）.</li><li>MiniTavern <strong>OpenRouter</strong>, Key 붙여넣기, 해당 ID.</li></ol><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>무료</td><td>ID에 <code>:free</code>, 또는 컬렉션 <code>$0</code>; 자동 라우트 <code>openrouter/free</code></td></tr><tr><td>속도</td><td>약 <strong>20 RPM / 약 50회/일</strong>; 일회 충전 약 <strong>$10+</strong> 후 무료 일 한도 약 <strong>1000회/일</strong>（공식 기준）</td></tr><tr><td>카드</td><td>무료는 보통 불필요; 충전은 한도 상향·유료 호출용</td></tr><tr><td>프라이버시</td><td>일부 무료 업스트림은 프롬프트로 개선; OpenRouter 설정에서 프라이버시. Poolside Laguna 등은 학습 가능 명시</td></tr></tbody></table><h2 id="모델-목록" tabindex="-1">모델 목록 <a class="header-anchor" href="#모델-목록" aria-label="Permalink to &quot;모델 목록&quot;">​</a></h2><p>컬렉션·공개 요약의 흔한 <strong>텍스트 / 비전</strong> ID（약 2026-08）; <strong>공식 기준</strong>. ID <strong>대소문자 구분</strong>, <code>:free</code> 생략 금지（항목에 없을 때 제외）.</p><h3 id="텍스트-·-자동-라우트" tabindex="-1">텍스트 · 자동 라우트 <a class="header-anchor" href="#텍스트-·-자동-라우트" aria-label="Permalink to &quot;텍스트 · 자동 라우트&quot;">​</a></h3><table tabindex="0"><thead><tr><th>모델 ID</th><th>설명</th></tr></thead><tbody><tr><td><code>openrouter/free</code></td><td>요청마다 가용 무료 선택; 가장 빠름, 품질 고정 아님</td></tr></tbody></table><h3 id="텍스트-·-일반-대화" tabindex="-1">텍스트 · 일반 대화 <a class="header-anchor" href="#텍스트-·-일반-대화" aria-label="Permalink to &quot;텍스트 · 일반 대화&quot;">​</a></h3><table tabindex="0"><thead><tr><th>모델 ID</th><th>설명</th></tr></thead><tbody><tr><td><code>meta-llama/llama-3.3-70b-instruct:free</code></td><td>종합, 다언어</td></tr><tr><td><code>meta-llama/llama-3.2-3b-instruct:free</code></td><td>경량</td></tr><tr><td><code>openai/gpt-oss-20b:free</code> / <code>openai/gpt-oss-120b:free</code></td><td>OpenAI OSS MoE</td></tr><tr><td><code>google/gemma-3-27b-it:free</code> / <code>google/gemma-3-12b-it:free</code> / <code>google/gemma-3-4b-it:free</code></td><td>Gemma 3</td></tr><tr><td><code>google/gemma-4-31b-it:free</code> / <code>google/gemma-4-26b-a4b-it:free</code></td><td>Gemma 4（일부 비전）</td></tr><tr><td><code>google/gemma-3n-e4b-it:free</code> / <code>google/gemma-3n-e2b-it:free</code></td><td>온디바이스 경량</td></tr><tr><td><code>qwen/qwen3-next-80b-a3b-instruct:free</code></td><td>Qwen3 대화</td></tr><tr><td><code>z-ai/glm-4.5-air:free</code></td><td>GLM 경량, 중국어 친화</td></tr><tr><td><code>minimax/minimax-m2.5:free</code></td><td>MiniMax</td></tr><tr><td><code>nousresearch/hermes-3-llama-3.1-405b:free</code></td><td>Hermes 3</td></tr><tr><td><code>arcee-ai/trinity-large-preview:free</code></td><td>Arcee Trinity Large Preview</td></tr><tr><td><code>openrouter/elephant-alpha</code></td><td>OpenRouter 호스팅（컬렉션/광장 Free 시）</td></tr><tr><td><code>cognitivecomputations/dolphin-mistral-24b-venice-edition:free</code></td><td>Venice Uncensored 변형（콘텐츠 척도 스스로）</td></tr></tbody></table><h3 id="텍스트-·-추론-agent-코딩" tabindex="-1">텍스트 · 추론 / Agent / 코딩 <a class="header-anchor" href="#텍스트-·-추론-agent-코딩" aria-label="Permalink to &quot;텍스트 · 추론 / Agent / 코딩&quot;">​</a></h3><table tabindex="0"><thead><tr><th>모델 ID</th><th>설명</th></tr></thead><tbody><tr><td><code>qwen/qwen3-coder:free</code></td><td>Qwen3 Coder</td></tr><tr><td><code>nvidia/nemotron-3-ultra:free</code>（또는 컬렉션 현재 ID）</td><td>Nemotron 3 Ultra, 장문 Agent</td></tr><tr><td><code>nvidia/nemotron-3.5-lightning:free</code></td><td>고처리량 Agent</td></tr><tr><td><code>nvidia/nemotron-3-super-120b-a12b:free</code></td><td>Nemotron 3 Super</td></tr><tr><td><code>nvidia/nemotron-3-nano-30b-a3b:free</code> / <code>nvidia/nemotron-nano-9b-v2:free</code></td><td>Nano</td></tr><tr><td><code>poolside/laguna-s-2.1:free</code> / <code>poolside/laguna-xs-2.1:free</code>（광장 ID）</td><td>Poolside 코딩 Agent; 무료는 학습 가능</td></tr><tr><td><code>cohere/north-mini-code:free</code>（광장）</td><td>Cohere North 코딩</td></tr><tr><td><code>liquid/lfm-2.5-1.2b-instruct:free</code> / <code>liquid/lfm-2.5-1.2b-thinking:free</code></td><td>Liquid 경량</td></tr><tr><td><code>dots-studio/dots3-note-preview:free</code>（광장）</td><td>Dots3-Note Preview</td></tr></tbody></table><p>사용량 정렬은 변함; 코딩은 <a href="https://openrouter.ai/collections/coding" target="_blank" rel="noreferrer">Coding</a>에서 Free 재필터.</p><h3 id="텍스트-·-비전-멀티모달-입력" tabindex="-1">텍스트 · 비전（멀티모달 입력） <a class="header-anchor" href="#텍스트-·-비전-멀티모달-입력" aria-label="Permalink to &quot;텍스트 · 비전（멀티모달 입력）&quot;">​</a></h3><p>주 모델이 비전을 지원하면 App 이미지 인식 / 멀티모달 직전 시 시범:</p><table tabindex="0"><thead><tr><th>모델 ID</th><th>설명</th></tr></thead><tbody><tr><td><code>google/gemma-3-27b-it:free</code> 등 Gemma 3/4</td><td>문+그림</td></tr><tr><td><code>nvidia/nemotron-nano-12b-v2-vl:free</code></td><td>비전 / 문서</td></tr><tr><td><code>nvidia/nemotron-3-nano-omni:free</code>（광장）</td><td>멀티모달 인지</td></tr><tr><td><code>meta-llama/llama-guard-4-12b:free</code></td><td>안전 분류 — 채팅 주 모델로는 비권장</td></tr></tbody></table><h3 id="이미지-비디오" tabindex="-1">이미지 / 비디오 <a class="header-anchor" href="#이미지-비디오" aria-label="Permalink to &quot;이미지 / 비디오&quot;">​</a></h3><ul><li><strong>이미지</strong>: OpenRouter <a href="https://openrouter.ai/collections/image-models" target="_blank" rel="noreferrer">Image Models</a>; 무료는 모델 페이지. MiniTavern 이미지 연결 <strong>OpenRouter</strong> 가능.</li><li><strong>비디오</strong>: <a href="https://openrouter.ai/collections/video-models" target="_blank" rel="noreferrer">Video Models</a>; App <strong>내장 비디오 없음</strong>.</li><li>Lyria 등 음악 생성은 채팅/이미지와 무관 — 대화 모델로 쓰지 말 것.</li></ul><h2 id="minitavern-입력" tabindex="-1">MiniTavern 입력 <a class="header-anchor" href="#minitavern-입력" aria-label="Permalink to &quot;MiniTavern 입력&quot;">​</a></h2><p>일반: <a href="/ultra_guides/ko/manual/model-link">모델 연결</a>.</p><h3 id="채팅" tabindex="-1">채팅 <a class="header-anchor" href="#채팅" aria-label="Permalink to &quot;채팅&quot;">​</a></h3><p>경로: <strong>설정 → 모델 → 모델 연결 → 새로 만들기</strong></p><ol><li><strong>OpenRouter</strong>（프리셋 Base URL）</li><li>API Key</li><li>예 <code>meta-llama/llama-3.3-70b-instruct:free</code> 또는 <code>openrouter/free</code></li><li><strong>테스트</strong> → 기본값</li></ol><p><strong>Custom (OpenAI)</strong> + Base URL <code>https://openrouter.ai/api/v1</code>도 가능; App 프리셋 우선.</p><h3 id="이미지" tabindex="-1">이미지 <a class="header-anchor" href="#이미지" aria-label="Permalink to &quot;이미지&quot;">​</a></h3><p>경로: <strong>설정 → 이미지 생성 → 이미지 연결</strong> → <strong>OpenRouter</strong>, 광장에서 이미지·무료（또는 과금 허용）ID. 더 안정적인 무료: <a href="/ultra_guides/ko/free-cloud/agnes-ai">Agnes AI</a>, <a href="/ultra_guides/ko/free-cloud/aihubmix">AIHubMix</a>.</p><h3 id="문제-해결" tabindex="-1">문제 해결 <a class="header-anchor" href="#문제-해결" aria-label="Permalink to &quot;문제 해결&quot;">​</a></h3><table tabindex="0"><thead><tr><th>현상</th><th>처리</th></tr></thead><tbody><tr><td><code>HTTP 429</code> / <code>Provider returned error</code></td><td>무료 풀 포화·한도: 다른 <code>:free</code>, 대기, <a href="https://openrouter.ai/settings/integrations" target="_blank" rel="noreferrer">BYOK</a></td></tr><tr><td>국내 접속 실패</td><td>공식 API에 프록시 필요할 수 있음; 국내 직결 벤더 / <a href="/ultra_guides/ko/free-cloud/aihubmix">AIHubMix</a></td></tr><tr><td>모델 404 / unavailable</td><td>해당 <code>:free</code> 오프라인: 컬렉션에서 ID 재복사</td></tr></tbody></table><p>더 보기: <a href="/ultra_guides/ko/manual/errors">오류</a>.</p><h2 id="관련-장" tabindex="-1">관련 장 <a class="header-anchor" href="#관련-장" aria-label="Permalink to &quot;관련 장&quot;">​</a></h2><ul><li><a href="/ultra_guides/ko/free-cloud/">무료 클라우드 개요</a></li><li><a href="/ultra_guides/ko/free-cloud/freellm">FreeLLM 목록</a></li><li><a href="/ultra_guides/ko/free-cloud/aihubmix">AIHubMix</a> — 보조금 <code>*-free</code></li><li><a href="/ultra_guides/ko/free-cloud/agnes-ai">Agnes AI</a> · <a href="/ultra_guides/ko/free-cloud/opencode-zen">OpenCode Zen</a></li><li><a href="/ultra_guides/ko/manual/model-link">모델 연결</a></li><li><a href="/ultra_guides/ko/free-cloud/#무료-이미지-생성">무료 이미지</a></li></ul>',35)])])}const p=t(d,[["render",n]]);export{f as __pageData,p as default};
